USE mydb;

INSERT INTO SEVERIDADE (id_severidade, nome, nivel, descricao) VALUES (1,
'Informativa - Incidente de TI 01', 1, 'Evento sem impacto relevante no serviço, registrado
para acompanhamento e rastreabilidade. Classificação 1 utilizada no processo de gestão,
priorização, atendimento e resolução de incidentes de TI.');
INSERT INTO SEVERIDADE (id_severidade, nome, nivel, descricao) VALUES (2, 'Baixa -
Incidente de TI 01', 2, 'Incidente com impacto limitado, normalmente resolvido pela equipe
de suporte em curto prazo. Classificação 2 utilizada no processo de gestão, priorização,
atendimento e resolução de incidentes de TI.');
INSERT INTO SEVERIDADE (id_severidade, nome, nivel, descricao) VALUES (3,
'Moderada - Incidente de TI 01', 3, 'Incidente com impacto perceptível em parte dos usuários
ou em um serviço de TI. Classificação 3 utilizada no processo de gestão, priorização,
atendimento e resolução de incidentes de TI.');
INSERT INTO SEVERIDADE (id_severidade, nome, nivel, descricao) VALUES (4, 'Alta -
Incidente de TI 01', 4, 'Incidente com impacto significativo em serviço, processo ou grupo de
usuários. Classificação 4 utilizada no processo de gestão, priorização, atendimento e
resolução de incidentes de TI.');
INSERT INTO SEVERIDADE (id_severidade, nome, nivel, descricao) VALUES (5, 'Crítica -
Incidente de TI 01', 5, 'Incidente com impacto severo ou indisponibilidade de serviço
essencial de TI. Classificação 5 utilizada no processo de gestão, priorização, atendimento e
resolução de incidentes de TI.');
INSERT INTO SEVERIDADE (id_severidade, nome, nivel, descricao) VALUES (6, 'Muito
Baixa - Incidente de TI 01', 1, 'Ocorrência de baixo impacto, sem interrupção significativa
dos serviços de tecnologia. Classificação 6 utilizada no processo de gestão, priorização,
atendimento e resolução de incidentes de TI.');
INSERT INTO SEVERIDADE (id_severidade, nome, nivel, descricao) VALUES (7,
'Controlada - Incidente de TI 01', 2, 'Incidente de impacto limitado e com contenção aplicada
pela equipe de TI. Classificação 7 utilizada no processo de gestão, priorização, atendimento
e resolução de incidentes de TI.');
INSERT INTO SEVERIDADE (id_severidade, nome, nivel, descricao) VALUES (8,
'Relevante - Incidente de TI 01', 3, 'Incidente que requer atuação técnica e
acompanhamento durante sua resolução. Classificação 8 utilizada no processo de gestão,
priorização, atendimento e resolução de incidentes de TI.');
INSERT INTO SEVERIDADE (id_severidade, nome, nivel, descricao) VALUES (9, 'Grave -
