INSERT INTO EQUIPE (id_equipe, nome, descricao, ativo, data_criacao) VALUES (1, 'Service Desk 01', 'Atendimento de primeiro nível para registro, classificação e acompanhamento de incidentes de TI. Equipe 01 destinada à gestão e ao tratamento de incidentes de TI.', 1, '2024-01-08 08:30:00');
